import{_ as s,C as t,o as n,c as i,j as a,a as l,E as o,aD as h}from"./chunks/framework.BpOiDbEB.js";const w=JSON.parse('{"title":"View settings","description":"","frontmatter":{},"headers":[],"relativePath":"en/majdatax/settings/view.md","filePath":"en/majdatax/settings/view.md","lastUpdated":1785607608000}'),c={name:"en/majdatax/settings/view.md"};function u(p,e,m,b,g,y){const d=t("NolebasePageProperties"),r=t("NolebaseGitChangelog");return n(),i("div",null,[e[0]||(e[0]=a("h1",{id:"view-settings",tabindex:"-1"},[l("View settings "),a("a",{class:"header-anchor",href:"#view-settings","aria-label":'Permalink to "View settings"'},"​")],-1)),o(d),e[1]||(e[1]=h('<h3 id="smooth-slide-animation" tabindex="-1">Smooth slide animation <a class="header-anchor" href="#smooth-slide-animation" aria-label="Permalink to &quot;Smooth slide animation&quot;">​</a></h3><p>Controls how slide arrows disappear when Autoplay is set to <code>Enable</code> or <strong>Mine Slide Auto-Advance</strong> is on. Arrows can disappear in groups based on the judgment area or one by one.</p><h3 id="auto-mode" tabindex="-1">Auto mode <a class="header-anchor" href="#auto-mode" aria-label="Permalink to &quot;Auto mode&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mode</th><th>Description</th></tr></thead><tbody><tr><td>Enable</td><td>Every note receives a Critical Perfect judgment, as enforced by the program.</td></tr><tr><td>DJAuto (Btn)</td><td>Simulates play with the outer buttons. It may occasionally produce Perfect judgments and includes full impossible-pattern checking.</td></tr><tr><td>DJAuto</td><td>Simulates an inner-screen player. It works like <code>DJAuto (Btn)</code> but does not press the outer buttons.</td></tr><tr><td>Random</td><td>Looks similar to <code>Enable</code>, but assigns judgments randomly.</td></tr><tr><td>Disable</td><td>Simulates manual play.</td></tr></tbody></table><p>In simulated-play modes, you can control the game with the mouse or touch screen. The <code>WEDCXZAQ</code> keys control the outer buttons.</p><p>DJAuto can detect impossible outer-button patterns and determine suitable techniques for touch groups. It sweeps across oversized and full-screen touch notes, merges contact points for overlapping slides and touches along a slide path, and continues to gain more human-like behavior.</p><h3 id="show-autoplay-hands" tabindex="-1">Show AutoPlay hands <a class="header-anchor" href="#show-autoplay-hands" aria-label="Permalink to &quot;Show AutoPlay hands&quot;">​</a></h3><p>When enabled, red circles represent touch events, light-green circles represent the coverage calculated for touch notes, and cyan circles represent triggered judgment areas.</p><h3 id="export-frame-rate" tabindex="-1">Export frame rate <a class="header-anchor" href="#export-frame-rate" aria-label="Permalink to &quot;Export frame rate&quot;">​</a></h3><p>Do not set the frame rate below 60 fps when exporting simulated Autoplay. Lower frame rates affect judgment accuracy.</p><h3 id="export-quality" tabindex="-1">Export quality <a class="header-anchor" href="#export-quality" aria-label="Permalink to &quot;Export quality&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Encoder</th><th>Rate-control mode</th><th>Low (0)</th><th>Medium (1)</th><th>High (2)</th><th>Ultra (3)</th></tr></thead><tbody><tr><td>libx264</td><td>CRF</td><td>28</td><td>23</td><td>18</td><td>14</td></tr><tr><td>h264_nvenc</td><td>CQ</td><td>30</td><td>24</td><td>18</td><td>14</td></tr><tr><td>h264_qsv</td><td>ICQ</td><td>32</td><td>25</td><td>18</td><td>14</td></tr><tr><td>h264_amf</td><td>QVBR</td><td>30</td><td>24</td><td>18</td><td>14</td></tr><tr><td>h264_mf</td><td>Bitrate (Mbps at 1080p60)</td><td>4</td><td>8</td><td>16</td><td>32</td></tr></tbody></table><h3 id="ui-skin" tabindex="-1">UI skin <a class="header-anchor" href="#ui-skin" aria-label="Permalink to &quot;UI skin&quot;">​</a></h3><p>Switch to <code>TrgUI</code> to use the side statistics interface designed by TRG.</p><h3 id="global-audio-delay" tabindex="-1">Global audio delay <a class="header-anchor" href="#global-audio-delay" aria-label="Permalink to &quot;Global audio delay&quot;">​</a></h3><p>This only changes the delay of <code>track</code> audio in preview mode. Because of differences between loading modes, the SFX delay is usually sufficient while the <code>track</code> delay is larger. A value of <code>0.03</code> works well on the author&#39;s computer, but the best value varies by device.</p><h3 id="use-the-legacy-star-layer-order" tabindex="-1">Use the legacy star layer order <a class="header-anchor" href="#use-the-legacy-star-layer-order" aria-label="Permalink to &quot;Use the legacy star layer order&quot;">​</a></h3><ul><li><strong>New order:</strong> New slides appear beneath older slides.</li><li><strong>Legacy order:</strong> New slides appear above older slides.</li></ul><h3 id="mine-slide-auto-advance" tabindex="-1">Mine Slide Auto-Advance <a class="header-anchor" href="#mine-slide-auto-advance" aria-label="Permalink to &quot;Mine Slide Auto-Advance&quot;">​</a></h3><p>Mine slides are normally completed by the rolling log. If you finish the slide before the log reaches the end, the slide receives a Miss judgment. <strong>Mine Slide Auto-Advance</strong> handles this progression automatically. Autoplay in <code>Enable</code> mode is not affected.</p>',20)),o(r)])}const v=s(c,[["render",u]]);export{w as __pageData,v as default};
